import React from 'react';
import { Navigate } from 'react-router-dom';
import { Container, Typography, Box, Button } from '@mui/material';
import { useAuth } from '../context/AuthContext';

const Dashboard = () => {
  const { currentUser } = useAuth();

  if (currentUser) {
    return <Navigate to={`/${currentUser.role}-dashboard`} />;
  }

  return (
    <Container maxWidth="lg" sx={{ mt: 8, textAlign: 'center' }}>
      <Typography variant="h2" component="h1" gutterBottom sx={{ fontWeight: 'bold' }}>
        Welcome to Career Guidance Platform
      </Typography>
      <Typography variant="h5" color="text.secondary" sx={{ mb: 4 }}>
        Your pathway to educational success and career opportunities in Lesotho
      </Typography>
      <Box sx={{ mt: 4 }}>
        <Typography variant="body1" sx={{ mb: 2 }}>
          Please register or login to access the platform features.
        </Typography>
      </Box>
    </Container>
  );
};

export default Dashboard;
